def car_race_collision(n: int):
    left_cars = [0] * n
    right_cars = [0] * n
    collisions = 0

    for i in range(n):
        left_cars[i] = i
        right_cars[i] = i

    for time_step in range(1, n):
        for i in range(n):
            left_cars[i] += 1
            right_cars[i] -= 1
            if left_cars[i] == right_cars[i]:
                collisions += 1

    return collisions

